#include <vector>
#include <limits>
#include <omp.h>

int smallestOdd(std::vector<int> const& x) {
    int global_min = std::numeric_limits<int>::max();

    #pragma omp parallel for reduction(min:global_min)
    for (std::size_t i = 0; i < x.size(); ++i) {
        if ((x[i] & 1) != 0) {
            if (x[i] < global_min) {
                global_min = x[i];
            }
        }
    }

    return global_min;
}
